function boatfix ()	--setElementCollisionsEnabled ( drugboat, false )endaddEventHandler ( "onClientResourceStart", getResourceRootElement(getThisResource()), boatfix )function createDrugJobMarker_func( player )	drugJobMarker = createMarker ( -2112.8369, 0, 34.5, "cylinder", 3, 255, 0, 0, 150 )endaddEvent ( "createDrugJobMarker", true )addEventHandler ( "createDrugJobMarker", getRootElement(), createDrugJobMarker_func )function destroyDrugJobMarker_func( player )	local pname = getPlayerName ( player )	destroyElement ( drugJobMarker )	destroyElement ( _G["drugJobPlaneMarker"..pname] )	destroyElement ( _G["drugLAPDBlip"..pname] )	destroyElement ( _G["drugLAPDMarker"..pname] )	destroyElement ( _G["drugPlaneMarker"..pname] )	destroyElement ( _G["drugAutoMarker"..pname] )	destroyElement ( _G["drugShipMarker"..pname] )	destroyElement ( _G["drugAutoBlip"..pname] )	destroyElement ( _G["drugShipBlip"..pname] )	destroyElement ( _G["drugMountainMarker"..pname] )	destroyElement ( _G["drugMountainBlip"..pname] )	destroyElement ( _G["mountainpackage1"..pname] )	destroyElement ( _G["mountainpackage2"..pname] )	destroyElement ( _G["mountainpackage3"..pname] )	destroyElement ( _G["mountainpackage4"..pname] )	drugmission = 0endaddEvent ( "destroyDrugJobMarker", true )addEventHandler ( "destroyDrugJobMarker", getRootElement(), destroyDrugJobMarker_func )function hitDrugJobMarker_func ( player )	local pname = getPlayerName ( player )	if getPedOccupiedVehicle ( player ) == false then		if source == drugJobMarker then			if player == getLocalPlayer() then				if tonumber ( getElementData ( player, "jobtime" ) ) == 0 then					destroyDrugJobMarker_func( player )					rnd = math.random( 1, 5 ) -- 1 = Flugzeug, 2 = LAPD, 3 = Auto, 4 = Ship, 5 = Mountain					if rnd == 1 then						planeDrugRoute( player )						drugJobPlaneMarker = createBlip ( -2301.7600097656, -2804.5095214844, 14.660495758057, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )					elseif rnd == 2 then						lapdDrugRoute( player )						curjob = "lapd"					elseif rnd == 3 then						autoDrugRoute( player )					elseif rnd == 4 then						shipDrugRoute( player )					elseif rnd == 5 then						mountainDrugRoute( player )					end				else					infobox_start_func("\n\nDu musst noch "..getElementData(player,"jobtime").." Minuten warten,\n bevor du die nächste Tour machen kannst!", 7500, 125, 0, 0 )				end			end		end		if source == _G["drugPlaneMarker"..pname] and player == getLocalPlayer() then			setTimer ( drugsAirplaneFoundClient, 3000, 1, player )			toggleAllControls ( false, true, false )		end		if source == _G["drugLAPDMarker"..pname] and player == getLocalPlayer() then			setTimer ( drugsLAPDFoundClient, 3000, 1, player )			toggleAllControls ( false, true, false )		end		if source == _G["drugAutoMarker"..pname] and player == getLocalPlayer() then			setTimer ( drugsAutoFoundClient, 3000, 1, player )			toggleAllControls ( false, true, false )		end		if source == _G["drugShipMarker"..pname] and player == getLocalPlayer() then			setTimer ( drugsNormalFoundClient, 3000, 1, player )			toggleAllControls ( false, true, false )		end		if source == _G["drugMountainMarker"..pname] and player == getLocalPlayer() then			setTimer ( drugsNormalFoundClient, 3000, 1, player )			toggleAllControls ( false, true, false )		end	endendaddEventHandler ( "onClientMarkerHit", getRootElement(), hitDrugJobMarker_func )function lapdDrugRoute( player )	local pname = getPlayerName ( player )	infobox_start_func("\n\nEinem Informanten zufolge wurde vom LAPD\neine grosse Menge Weed beschlagnahmt.", 7500, 125, 0, 0 )	_G["drugLAPDBlip"..pname] = createBlip ( -1605.7623291016, 711.326171875, 14, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )	_G["drugLAPDMarker"..pname] = createMarker ( 223.98358154297, 127.49185180664, 1009.2152099609, "cylinder", 1.5, 255, 255, 255, 150 )	setElementInterior ( drugLAPDMarker, 10 )endfunction drugsNormalFoundClient ( player )	rnd = math.random ( 1, 4 )	destroyDrugJobMarker_func( player )	if rnd == 1 or rnd == 2 then		drugsfound = math.random ( 50, 100 )		infobox_start_func("\n\nDu hast soeben "..drugsfound.." Gramm Weed gefunden!", 7500, 0, 125, 0 )	elseif rnd == 3 then		drugsfound = math.random ( 10, 25 )		infobox_start_func("\n\nDie Beutel sind völlig zerfetzt! Du hast\nnur noch "..drugsfound.." Gramm Weed retten können!", 7500, 200, 200, 0 )	elseif rnd == 4 then		infobox_start_func("\n\nOffenbar war jemand vor dir da!\nDas ganze Weed ist schon weg!", 7500, 125, 0, 0 )		drugsfound = "nil"	end	toggleAllControls ( true )	createDrugJobMarker_func( player )	triggerServerEvent ( "drugRecieve", player, drugsfound )endfunction drugsAirplaneFoundClient ( player)	rnd = math.random ( 1, 6 )	destroyDrugJobMarker_func( player )	if rnd == 1 or rnd == 2 or rnd == 3 then		drugsfound = math.random ( 50, 100 )		infobox_start_func("\n\nDu hast soeben "..drugsfound.." Gramm Weed gefunden!", 7500, 0, 125, 0 )	elseif rnd == 4 then		drugsfound = math.random ( 10, 25 )		infobox_start_func("\n\nDie Beutel sind völlig zerfetzt! Du hast\nnur noch "..drugsfound.." Gramm Weed retten können!", 7500, 200, 200, 0 )	elseif rnd == 5 then		infobox_start_func("\n\nEs ist eine Falle!\nDie Cops haben dich beobachtet!", 7500, 125, 0, 0 )		drugsfound = "cops"	elseif rnd == 6 then		infobox_start_func("\n\nDer Tank des Flugzeugs ist in\nFlammen aufgegangen! RENN!!!", 7500, 125, 0, 0 )		createFire ( -2301.7600097656, -2804.5095214844, 14.660495758057, 3 )		drugsfound = "boom"	end	toggleAllControls ( true )	createDrugJobMarker_func( player )	triggerServerEvent ( "drugRecieve", player, drugsfound )endfunction drugsLAPDFoundClient ( player )	rnd = math.random ( 1, 5 )	destroyDrugJobMarker_func( player )	if rnd == 1 or rnd == 2 then		drugsfound = math.random ( 50, 100 )		infobox_start_func("\n\nDu hast soeben "..drugsfound.." Gramm Weed gefunden!", 7500, 0, 125, 0 )	elseif rnd == 3 then		drugsfound = math.random ( 10, 25 )		infobox_start_func("\n\nDie Beutel sind völlig zerfetzt! Du hast\nnur noch "..drugsfound.." Gramm Weed retten können!", 7500, 200, 200, 0 )	elseif rnd == 4 then		infobox_start_func("\n\nEs ist eine Falle!\nDie Cops haben dich beobachtet!", 7500, 125, 0, 0 )		drugsfound = "cops"	elseif rnd == 5 then		infobox_start_func("\n\nOffenbar war jemand vor dir da!\nDas ganze Weed ist schon weg!", 7500, 125, 0, 0 )		drugsfound = "nil"	end	toggleAllControls ( true )	createDrugJobMarker_func( player )	triggerServerEvent ( "drugRecieve", player, drugsfound )endfunction drugsAutoFoundClient ( player )	rnd = math.random ( 1, 5 )	destroyDrugJobMarker_func( player )	if rnd == 1 or rnd == 2 then		drugsfound = math.random ( 50, 100 )		infobox_start_func("\n\nDu hast soeben "..drugsfound.." Gramm Weed gefunden!", 7500, 0, 125, 0 )	elseif rnd == 3 then		drugsfound = math.random ( 10, 25 )		infobox_start_func("\n\nDer Beutel ist völlig zerfetzt! Du hast\nnur noch "..drugsfound.." Gramm Weed retten können!", 7500, 200, 200, 0 )	elseif rnd == 4 then		infobox_start_func("\n\nEs ist eine Falle!\nDie Cops haben dich beobachtet!", 7500, 125, 0, 0 )		drugsfound = "cops"	elseif rnd == 5 then		infobox_start_func("\n\nDer Tank des Autos ist in\nFlammen aufgegangen! RENN!!!", 7500, 125, 0, 0 )		createFire ( -1854.169, -1677.076, 22.04, 3 )		drugsfound = "boomauto"	end	toggleAllControls ( true )	createDrugJobMarker_func( player )	triggerServerEvent ( "drugRecieve", player, drugsfound )endfunction planeDrugRoute ( player )	local pname = getPlayerName ( player )	infobox_start_func("\n\nEinem Informanten zufolge ist in County\nein Flugzeug abgestürzt. Berge das Weed!", 7500, 125, 0, 0 )	_G["drugPlaneMarker"..pname] = createMarker ( -2311.2800292969, -2804.0612792969, 11.192306518555, "cylinder", 2, 255, 255, 255, 150)endfunction LAPDEnterClient_func ( player )	if drugLAPDBlip then		infobox_start_func("\n\nDas Weed befindet sich im oberen Stockwerk!", 7500, 125, 0, 0 )		local pname = getPlayerName ( player )		destroyElement ( _G["drugLAPDBlip"..pname] )	endendaddEvent ( "LAPDEnterClient", true )addEventHandler ( "LAPDEnterClient", getRootElement(), LAPDEnterClient_func )function autoDrugRoute ( player )	local pname = getPlayerName ( player )	infobox_start_func("\n\nGemäss einer vertraulicher Info\ngibt es Weed in einem Auto beim Mülljob!", 7500, 125, 0, 0 )	_G["drugAutoMarker"..pname] = createMarker ( -1856.3681, -1678.4321, 20.856, "cylinder", 2, 255, 255, 255, 150 )	_G["drugAutoBlip"..pname] = createBlip ( -1856.3681, -1678.4321, 14, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )endfunction shipDrugRoute ( player )	local pname = getPlayerName ( player )	infobox_start_func("\n\nEin Küstenwacheschiff ist beim\nMülljob untergegangen! Berge das Weed!", 7500, 125, 0, 0 )	_G["drugShipMarker"..pname] = createMarker ( -1857.798, -1491.508, -8.8113, "cylinder", 2, 255, 255, 255, 150 )	_G["drugShipBlip"..pname] = createBlip ( -1857.798, -1491.508, 14, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )endfunction mountainDrugRoute ( player )	local pname = getPlayerName ( player )	infobox_start_func("\n\nAuf einem Berg wurde Weed entdeckt!\nReiss es dir unter den Nagel!", 7500, 125, 0, 0 )	_G["drugMountainMarker"..pname] = createMarker ( -1426.708, -957.754, 200, "cylinder", 2, 255, 255, 255, 150 )	_G["drugMountainBlip"..pname] = createBlip ( -1435.607, -964.184, 14, 0, 2, 255, 0, 0, 255, 0, 99999.0, player )	_G["mountainpackage1"..pname] = createObject(1279, -1427.967, -958.68, 199.95, 0, 0, 0)	_G["mountainpackage2"..pname] = createObject(1279, -1425.4, -958.68, 199.95, 0, 0, 0)	_G["mountainpackage3"..pname] = createObject(1279, -1425.4, -957.119, 199.95, 0, 0, 0)	_G["mountainpackage4"..pname] = createObject(1279, -1427.967, -957.119, 199.95, 0, 0, 0)end